                ("motor_left", (57, 56, 57)),
                ("motor_right", (57, 56, 57)),
                ("bracket_left", (70, 5, 70)),
            ]
        )
    )
    assert values(found) == {"wheel_radius_mm": 60.0, "n_drive_motors": 2, "mass_kg": 5.4}
    assert "estimate" in next(f for f in found if f.field == "mass_kg").evidence

